import math

def check_triangle(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return False
    s = (a + b + c) / 2
    area_sq = s * (s - a) * (s - b) * (s - c)
    if area_sq < 0:
        return False
    area = math.sqrt(area_sq)
    r = area / s
    return math.isclose(r, 1.0)

found = []
for n in range(1, 100):
    sides = [n, n+1, n+2]
    if check_triangle(*sides):
        found.append(sum(sides))

print(f"Found perimeters: {found}")

